 let origin=[...homes[$('area').value]],map,originMarker,destinationMarker,seq=0;
 function invalidate(){seq++;$('weatherRows').replaceChildren();$('weatherHint').textContent='';$('weatherStatus').textContent=t('地点、日期或课程时间已变更，请重新查询。','Location, date or class time changed. Load the forecast again.');$('weatherBadge').textContent=t('天气：需重新查询','Weather: refresh required');}
 function location(){const dest=approx[$('building').value];if(map){originMarker.setLatLng(origin);destinationMarker.setLatLng(dest).bindPopup($('building').selectedOptions[0].textContent+' · '+t('示意位置，入口未核验','Approximate; entrance unverified'));map.fitBounds([origin,dest],{padding:[35,35],maxZoom:16});}$('originLat').value=origin[0].toFixed(5);$('originLon').value=origin[1].toFixed(5);$('locationNote').textContent=t('天气起点坐标：','Forecast origin coordinates: ')+origin.map(x=>x.toFixed(5)).join(', ');}
 $('setOrigin').onclick=()=>{const lat=Number($('originLat').value),lon=Number($('originLon').value);if(!$('originLat').value||!$('originLon').value||lat<52.3||lat>52.65||lon< -2.1||lon> -1.65){$('mapStatus').textContent=t('请输入伯明翰范围内的有效坐标。','Enter valid coordinates within the Birmingham area.');return;}origin=[lat,lon];location();invalidate();};
