 $('getWeather').onclick=async()=>{const version=++seq;const d=date.value;if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||d<isoDay||d>maxDay.toISOString().slice(0,10)){$('weatherStatus').textContent=t('请选择今天起七天内的日期；更远日期暂不提供预报。','Choose a date within seven days from today; forecasts beyond this range are not offered.');$('weatherRows').replaceChildren();$('weatherBadge').textContent=t('天气：超出查询范围','Weather: outside supported range');return;}const point=$('weatherPlace').value==='campus'?[52.4508,-1.9305]:origin;const place=$('weatherPlace').selectedOptions[0].textContent;const u=new URL('https://api.open-meteo.com/v1/forecast');Object.entries({latitude:point[0],longitude:point[1],hourly:'temperature_2m,precipitation_probability,precipitation,wind_speed_10m',timezone:'Europe/London',timeformat:'unixtime',forecast_days:7}).forEach(([k,v])=>u.searchParams.set(k,v));$('weatherStatus').textContent=t('正在获取预报…','Fetching forecast…');$('weatherRows').replaceChildren();$('weatherHint').textContent='';$('weatherBadge').textContent=t('天气：查询中','Weather: loading');try{const r=await fetch(u,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();const j=await r.json();if(version!==seq)return;if(!Array.isArray(j.hourly?.time))throw Error();const h=Number($('classStart').value.split(':')[0]);const format=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});let count=0,rain=false;const cell=v=>v===null||v===undefined?'—':String(v);j.hourly.time.forEach((stamp,i)=>{const at=new Date(stamp*1000);const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'}).format(at);const time=format.format(at),hour=Number(time.slice(0,2));if(parts!==d||hour<Math.max(0,h-2)||hour>Math.min(23,h+1))return;count++;const a=j.hourly;rain ||= (a.precipitation_probability?.[i]??0)>=50;const row=document.createElement('tr');[time,cell(a.temperature_2m?.[i]),cell(a.precipitation_probability?.[i])+(a.precipitation_probability?.[i]==null?'':'%'),cell(a.precipitation?.[i]),cell(a.wind_speed_10m?.[i])].forEach(v=>{const td=document.createElement('td');td.textContent=v;row.append(td);});$('weatherRows').append(row);});if(!count)throw Error();$('weatherBadge').textContent=t('天气：已获取预测数据','Weather: forecast retrieved');$('weatherStatus').textContent=place+' · Open-Meteo · '+t('获取时间 ','Retrieved ')+new Date().toLocaleString(en?'en-GB':'zh-CN',{timeZone:'Europe/London'})+' · '+point.map(x=>x.toFixed(4)).join(', ');$('weatherHint').textContent=rain?t('该时段部分小时降雨概率 ≥50%，可考虑雨具和额外余量；这不是降雨保证。','Some hours have ≥50% rain probability. Consider rainwear and extra time; rainfall is not guaranteed.'):t('未发现 ≥50% 的小时降雨概率；仍请留意预报变化。','No displayed hour has ≥50% rain probability. Forecasts may still change.');}catch{if(version!==seq)return;$('weatherBadge').textContent=t('天气：暂不可用','Weather: unavailable');$('weatherStatus').textContent=t('天气请求失败，请稍后重试。未使用模拟天气替代。','Forecast request failed. Try again later. No simulated weather substituted.');}};
